CREATE TABLE users(id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) UNIQUE,password VARCHAR(255),name VARCHAR(255),role VARCHAR(30)); CREATE TABLE category(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) UNIQUE,description VARCHAR(500)); CREATE TABLE product(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255),description TEXT,price DOUBLE,power_watts DOUBLE,image_url VARCHAR(500),active BOOLEAN,category_id BIGINT,FOREIGN KEY(category_id) REFERENCES category(id)); CREATE TABLE quote(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT,monthly_kwh DOUBLE,roof_area DOUBLE,estimated_kw DOUBLE,estimated_cost DOUBLE,status VARCHAR(30),created_at TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)); INSERT INTO category(name,description) VALUES('Solar Panels','High efficiency photovoltaic panels'),('Inverters','Reliable grid-tie inverters');
